python -c 'import os,re,pathlib
for label,limit in [("default",2),("proxy",4)]:
    lines=(pathlib.Path(os.environ["TEMP"])/f"C-AUD-PROXY-{label}-tests.txt").read_text(encoding="utf-8-sig").splitlines()
    unit=doc=0; in_doc=False
    for line in lines:
        if "Doc-tests" in line: in_doc=True
        m=re.search(r"test result:.* (\d+) ignored",line)
        if m:
            if in_doc: doc+=int(m.group(1))
            else: unit+=int(m.group(1))
    print(label,"unit",unit,"doc",doc,"limit",limit)
    assert unit==0 and doc<=limit
print("c7.3 PASS")'
